(() => {
  if (window.__qrhook) return 'already';
  window.__qrhook = true;
  const stash = (txt) => {
    try {
      const j = JSON.parse(txt);
      const u = j && j.data && j.data.url;
      if (!u) return;
      const p = new URL(u).searchParams;
      window.__xhs_qr = {
        url: u,
        qr_id: p.get('qrId') || p.get('qr_id') || '',
        code: p.get('xhs_code') || p.get('code') || ''
      };
    } catch (e) {}
  };
  const hit = (u) => /\/api\/sns\/web\/v1\/login\/qrcode\/create/.test(String(u));
  const O = XMLHttpRequest.prototype.open, S = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function (m, u) {
    this.__qr_u = String(u);
    return O.apply(this, arguments);
  };
  XMLHttpRequest.prototype.send = function () {
    if (hit(this.__qr_u)) this.addEventListener('loadend', () => stash(this.responseText));
    return S.apply(this, arguments);
  };
  const F = window.fetch;
  window.fetch = function (u) {
    const us = String(typeof u === 'object' && u ? u.url : u);
    const p = F.apply(this, arguments);
    if (hit(us)) return p.then((r) => { r.clone().text().then(stash).catch(() => {}); return r; });
    return p;
  };
  return 'hooked';
})()

args.script:
(async () => {
  const deadline = Date.now() + 20000;
  while (Date.now() < deadline) {
    if (window.__xhs_qr && window.__xhs_qr.url && window.__xhs_qr.qr_id && window.__xhs_qr.code) {
      return JSON.stringify(Object.assign({ source: 'page' }, window.__xhs_qr));
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  if (typeof window._webmsxyw !== 'function') {
    throw new Error('page QR missing and _webmsxyw not ready for manual create');
  }
  const path = '/api/sns/web/v1/login/qrcode/create';
  const body = { qr_type: 1 };
  const sg = window._webmsxyw(path, body);
  const r = await fetch('https://edith.xiaohongshu.com' + path, {
    method: 'POST', credentials: 'include',
    headers: {
      'content-type': 'application/json',
      'x-s': String((sg && sg['X-s']) || ''),
      'x-t': String((sg && sg['X-t']) || '')
    },
    body: JSON.stringify(body)
  });
  const j = await r.json();
  const u = j && j.data && j.data.url;
  if (!u) throw new Error('qrcode/create has no data.url: ' + JSON.stringify(j).slice(0, 240));
  const p = new URL(u).searchParams;
  const qr = {
    source: 'manual',
    url: u,
    qr_id: p.get('qrId') || p.get('qr_id') || '',
    code: p.get('xhs_code') || p.get('code') || ''
  };
  if (!qr.qr_id || !qr.code) throw new Error('cannot parse qrId/code from ' + u.slice(0, 120));
  window.__xhs_qr = qr;
  return JSON.stringify(qr);
})()

(async () => {
  const qr = window.__xhs_qr;
  if (!qr || !qr.url) throw new Error('no __xhs_qr.url — ensure_qr failed?');
  if (typeof qrcode !== 'function') {
    throw new Error('qrcode lib missing — preload recipe xhs-qrcode before navigate');
  }
  const q = qrcode(0, 'M');
  q.addData(qr.url);
  q.make();
  const svg = q.createSvgTag({ cellSize: 8, margin: 4 });
  const dataUrl = 'data:image/svg+xml;base64,' + btoa(svg);
  window.__xhs_qr_data = dataUrl;
  let panel = document.getElementById('__xhs_qr_panel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = '__xhs_qr_panel';
    panel.setAttribute('data-testid', 'xhs-qr-panel');
    panel.style.cssText = 'position:fixed;z-index:2147483646;left:50%;top:50%;transform:translate(-50%,-50%);padding:20px;background:#fff;border-radius:16px;box-shadow:0 8px 40px rgba(0,0,0,.35);';
    document.documentElement.appendChild(panel);
  }
  panel.innerHTML = '';
  const img = document.createElement('img');
  img.id = '__xhs_qr_img';
  img.alt = 'xhs-login-qr';
  img.width = 280;
  img.height = 280;
  img.src = dataUrl;
  panel.appendChild(img);
  return dataUrl;
})()

(async () => {
  const qr = window.__xhs_qr;
  if (!qr || !qr.qr_id || !qr.code) throw new Error('no __xhs_qr — ensure_qr step failed?');
  if (typeof window._webmsxyw !== 'function') throw new Error('_webmsxyw missing — cannot sign status poll');
  const budget = Number({{login_timeout_ms}}) || 120000;
  const deadline = Date.now() + Math.min(budget, 120000);
  let last = null;
  let sawScan = false;
  while (Date.now() < deadline) {
    const path = '/api/sns/web/v1/login/qrcode/status?qr_id=' + encodeURIComponent(qr.qr_id)
      + '&code=' + encodeURIComponent(qr.code);
    const sg = window._webmsxyw(path, undefined);
    const r = await fetch('https://edith.xiaohongshu.com' + path, {
      credentials: 'include',
      headers: {
        'x-s': String((sg && sg['X-s']) || ''),
        'x-t': String((sg && sg['X-t']) || '')
      }
    });
    const text = await r.text();
    let st = null;
    try { st = JSON.parse(text).data.code_status; } catch (e) {}
    last = { code_status: st, raw: String(text).slice(0, 200) };
    if (st === 1) sawScan = true;
    if (st === 2) {
      return JSON.stringify({ ok: true, code_status: 2, qr_id: qr.qr_id });
    }
    if (st === 3 || st === 471) {
      throw new Error(
        'QR rejected/expired (code_status=' + st + '). ' +
        'If the App showed 环境异常: re-run with vars.mode="cookies" and vars.import_cookies=' +
        '[Set-Cookie strings from Chrome DevTools on creator.xiaohongshu.com] — same jar shape as import_curl. ' +
        'last=' + JSON.stringify(last)
      );
    }
    await new Promise((r) => setTimeout(r, 2500));
  }
  throw new Error(
    'no confirmation within budget' + (sawScan ? ' (saw scanned=1 but never confirmed)' : ' (never scanned)') +
    '. Phone must scan saved.qr_data / #__xhs_qr_panel (or /live?session=). ' +
    'If App 环境异常: vars.mode=cookies + import_cookies from Chrome. last=' + JSON.stringify(last)
  );
})()

(async () => {
  const jar = document.cookie || '';
  const has = /(?:^|;\s*)web_session=/.test(jar);
  return JSON.stringify({
    url: location.href,
    title: document.title,
    web_session_in_document_cookie: has,
    hint: 'prefer GET /session/:id/cookies — HttpOnly web_session may be hidden from document.cookie'
  });
})()

(async () => {
  const path = '/api/sns/web/v1/user/me';
  const headers = { 'content-type': 'application/json' };
  if (typeof window._webmsxyw === 'function') {
    const sg = window._webmsxyw(path, undefined);
    if (sg && sg['X-s']) {
      headers['x-s'] = String(sg['X-s']);
      headers['x-t'] = String(sg['X-t']);
    }
  }
  const r = await fetch('https://edith.xiaohongshu.com' + path, {
    credentials: 'include',
    headers
  });
  const text = await r.text();
  let code = null, guest = null;
  try {
    const j = JSON.parse(text);
    code = j.code;
    guest = j.data && j.data.guest;
  } catch (e) {}
  if (code === 0 && guest !== true) {
    return JSON.stringify({ ok: true, via: 'user/me', code: 0, url: location.href });
  }
  throw new Error('cookies import did not yield a logged-in user/me (code=' + code + ', guest=' + guest + ', body=' + text.slice(0, 180) + ').
})()

